body { font-family: system-ui, sans-serif; padding: 16px; }
:root {
  --brand: #0b6fd6;
  --radius: 8px;
  --space: 1rem;
}
h1 { color: var(--brand); font-size: clamp(1.5rem, 5vw, 3rem); }
.btn {
  background: var(--brand);
  color: white;
  border: 0;
  border-radius: var(--radius);
  padding: calc(var(--space) / 2) var(--space);
}

